module Fastlane
  module Actions
    class ZipAction < Action
      class ZipFilterSet
        attr_reader :include, :exclude, :params

        def initialize(include_paths, exclude_paths, params)
          @include = include_paths
          @exclude = exclude_paths
          @params = params
        end
      end

      class Runner
        attr_reader :output_path, :path, :verbose, :password, :symlinks, :include, :exclude, :path_details

        def initialize(params)
          @output_path = File.expand_path(params[:output_path] || params[:path])
          @path = params[:path]
          @verbose = params[:verbose]

require_relative 'ui/ui'
require_relative 'globals'
require_relative 'fastlane_pty'

module FastlaneCore
  class ZipCommandFlags
    attr_reader :recursive, :quiet_suffix, :symlink_flag, :filter_set

    def initialize(verbose, symlinks, filter_set)
      @recursive = "r"
      @quiet_suffix = verbose ? "" : "q"
      @symlink_flag = symlinks ? "y" : ""
      @filter_set = filter_set
    end
  end

  # Executes commands and takes care of error handling and more
  class CommandExecutor
    attr_reader :binary_name

